#!/usr/bin/env node
/* global console */
/**
 * Generate the local AI reasoning capability snapshot from models.dev.
 *
 * Source: anomalyco/models.dev (MIT), https://models.dev/api.json
 * The generated file is committed so API boot and tests never depend on the
 * network. Refresh it deliberately when the upstream catalog changes.
 *
 * Usage:
 *   node tooling/scripts/generate-ai-model-capabilities.mjs \
 *     --source /tmp/models-dev.json \
 *     --commit 5192a691eea9a5e890caa31ec47983a2da31f7e6 \
 *     --out apps/api/src/common/data/models-dev-reasoning.generated.ts
 */

import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import process from "node:process";

const EFFORT_ORDER = ["none", "minimal", "low", "medium", "high", "xhigh", "max"];
const EFFORT_SET = new Set(EFFORT_ORDER);

function argument(name, fallback) {
  const index = process.argv.indexOf(`--${name}`);
  return index >= 0 && process.argv[index + 1] ? process.argv[index + 1] : fallback;
}

function normalize(value) {
  return value.trim().toLowerCase().replaceAll("_", "-");
}

function effortsFor(model) {
  const values = new Set();
  for (const option of model.reasoning_options ?? []) {
    if (!option || option.type !== "effort" || !Array.isArray(option.values)) continue;
    for (const value of option.values) {
      if (typeof value === "string" && EFFORT_SET.has(value)) {
        values.add(value);
      }
    }
  }
  return [...values].sort(
    (left, right) => EFFORT_ORDER.indexOf(left) - EFFORT_ORDER.indexOf(right),
  );
}

const sourcePath = argument("source", "");
const commit = argument("commit", "unknown");
const outputPath = path.resolve(
  argument("out", "apps/api/src/common/data/models-dev-reasoning.generated.ts"),
);

if (!sourcePath) {
  throw new Error("--source is required (path to models.dev api.json)");
}

const catalog = JSON.parse(await readFile(sourcePath, "utf8"));
const byProviderModel = new Map();
const byCanonical = new Map();
const bareCandidates = new Map();

for (const providerId of Object.keys(catalog)) {
  for (const [modelId, model] of Object.entries(catalog[providerId]?.models ?? {})) {
    const efforts = effortsFor(model);
    if (efforts.length === 0) continue;

    const normalizedProvider = normalize(providerId);
    const normalizedModel = normalize(modelId);
    byProviderModel.set(`${normalizedProvider}/${normalizedModel}`, efforts);

    if (typeof model.canonical_model_id === "string") {
      byCanonical.set(normalize(model.canonical_model_id), efforts);
    }

    const bare = bareCandidates.get(normalizedModel) ?? new Set();
    bare.add(efforts.join("|"));
    bareCandidates.set(normalizedModel, bare);
  }
}

const byBare = {};
for (const [modelId, signatures] of [...bareCandidates.entries()].sort(([left], [right]) =>
  left.localeCompare(right),
)) {
  if (signatures.size !== 1) continue;
  const [signature] = signatures;
  byBare[modelId] = signature.split("|");
}

function sortedObject(entries) {
  return Object.fromEntries(
    [...entries.entries()].sort(([left], [right]) => left.localeCompare(right)),
  );
}

const payload = {
  source: "anomalyco/models.dev",
  sourceUrl: "https://models.dev/api.json",
  repoUrl: "https://github.com/anomalyco/models.dev",
  commit,
  license: "MIT",
  generatedAt: new Date().toISOString(),
  byProviderModel: sortedObject(byProviderModel),
  byCanonical: sortedObject(byCanonical),
  byBare,
};

const body = `/* eslint-disable */
/**
 * Generated by tooling/scripts/generate-ai-model-capabilities.mjs.
 * Source: ${payload.repoUrl} @ ${payload.commit} (MIT).
 * Do not edit by hand. Refresh with:
 *   node tooling/scripts/generate-ai-model-capabilities.mjs --source <models.dev-api.json> --commit <sha> --out apps/api/src/common/data/models-dev-reasoning.generated.ts
 */
import type { AiReasoningEffort } from "@roamlog/contracts";

export interface ModelsDevReasoningSnapshot {
  readonly source: string;
  readonly sourceUrl: string;
  readonly repoUrl: string;
  readonly commit: string;
  readonly license: string;
  readonly generatedAt: string;
  readonly byProviderModel: Readonly<Record<string, readonly AiReasoningEffort[]>>;
  readonly byCanonical: Readonly<Record<string, readonly AiReasoningEffort[]>>;
  readonly byBare: Readonly<Record<string, readonly AiReasoningEffort[]>>;
}

export const MODELS_DEV_REASONING: ModelsDevReasoningSnapshot = ${JSON.stringify(payload)};
`;

await mkdir(path.dirname(outputPath), { recursive: true });
await writeFile(outputPath, body, "utf8");
console.log(
  `wrote ${outputPath}: ${Object.keys(payload.byProviderModel).length} provider/model, ` +
    `${Object.keys(payload.byCanonical).length} canonical, ${Object.keys(payload.byBare).length} bare`,
);
